"""Small real FIT fixtures generated by dtc/mkimage, never firmware builds."""
from pathlib import Path
import subprocess


def make_fit(directory, *, external=True, position=None):
    """Return a hashed kernel/FDT/rootfs FIT; directory must already exist.

    External data uses data-offset by default; position selects data-position.
    """
    directory = Path(directory)
    (directory / 'kernel.bin').write_bytes(b'fixture kernel payload\n' * 3)
    (directory / 'rootfs.bin').write_bytes(b'fixture rootfs payload\n' * 4)
    (directory / 'board.dts').write_text('/dts-v1/; / { compatible = "gemtek,w1700k-ubi"; };\n')
    subprocess.run(['dtc', '-I', 'dts', '-O', 'dtb', '-o', 'board.dtb', 'board.dts'],
                   cwd=directory, check=True, capture_output=True)
    (directory / 'fixture.its').write_text('''/dts-v1/;
/ {
    description = "W1700K test FIT";
    #address-cells = <1>;
    images {
        kernel-1 {
            description = "kernel";
            data = /incbin/("kernel.bin");
            type = "kernel"; arch = "arm64"; os = "linux";
            compression = "none"; load = <0x80200000>; entry = <0x80200000>;
            hash-1 { algo = "crc32"; };
            hash-2 { algo = "sha1"; };
            hash-3 { algo = "sha256"; };
        };
        fdt-1 {
            description = "fdt";
            data = /incbin/("board.dtb");
            type = "flat_dt"; arch = "arm64"; compression = "none";
            hash-1 { algo = "sha256"; };
        };
        rootfs-1 {
            description = "rootfs";
            data = /incbin/("rootfs.bin");
            type = "filesystem"; arch = "arm64"; compression = "none";
            hash-1 { algo = "sha256"; };
        };
    };
    configurations {
        default = "config-1";
        config-1 { kernel = "kernel-1"; fdt = "fdt-1"; loadables = "rootfs-1"; };
    };
};
''')
    command = ['mkimage', '-f', 'fixture.its']
    if external:
        command += ['-E']
    if position is not None:
        command += ['-p', hex(position)]
    subprocess.run(command + ['fixture.itb'], cwd=directory, check=True, capture_output=True)
    return (directory / 'fixture.itb').read_bytes()
